class OrderItemSerializer(serializers.ModelSerializer):
    class Meta:
        model = OrderItem
        fields = ["product", "quantity"]

class OrderSerializer(serializers.ModelSerializer):
    items = OrderItemSerializer(many=True)

    class Meta:
        model = Order
        fields = ["id", "customer", "items", "status"]
        read_only_fields = ["customer", "status"]

    def create(self, validated_data):
        items = validated_data.pop("items")
        with transaction.atomic():
            order = Order.objects.create(customer=self.context["request"].user, **validated_data)
            OrderItem.objects.bulk_create(
                [OrderItem(order=order, **item) for item in items]
            )
        return order

class OrderViewSet(viewsets.ModelViewSet):
    serializer_class = OrderSerializer
    permission_classes = [IsAuthenticated]

    def get_queryset(self):
        return Order.objects.filter(customer=self.request.user).prefetch_related("items")

    def perform_create(self, serializer):
        serializer.save(customer=self.request.user)

