from contextvars import ContextVar

_current_tenant = ContextVar("current_tenant", default=None)

class TenantQuerySet(models.QuerySet):
    def for_tenant(self, tenant):
        if tenant is None:
            raise ValueError("Tenant is required")
        return self.filter(tenant=tenant)

class TenantManager(models.Manager.from_queryset(TenantQuerySet)):
    def get_queryset(self):
        tenant = _current_tenant.get()
        qs = super().get_queryset()
        return qs.filter(tenant=tenant) if tenant else qs.none()

class TenantMiddleware:
    def __init__(self, get_response):
        self.get_response = get_response

    def __call__(self, request):
        host = request.get_host().split(":")[0]
        tenant = Tenant.objects.filter(domain=host, active=True).first()
        if tenant is None:
            raise Http404("Unknown workspace")
        if request.user.is_authenticated and not request.user.tenants.filter(pk=tenant.pk).exists():
            raise PermissionDenied
        request.tenant = tenant
        token = _current_tenant.set(tenant)
        try:
            return self.get_response(request)
        finally:
            _current_tenant.reset(token)
